// This should only be used when the VoiceServerUpdate will be intercepted and used elsewhere.
//
//	gID     : Guild ID of the channel to join.
//	cID     : Channel ID of the channel to join, leave empty to disconnect.
//	mute    : If true, you will be set to muted upon joining.
//	deaf    : If true, you will be set to deafened upon joining.

// ChannelVoiceJoinManualContext sends the typed voice-state update on the
// shared main Gateway, for a host-owned voice transport. Empty cID disconnects
// with JSON null. It neither opens a voice socket nor retries the update.

methods.body:
var channelID *string
if cID != "" {
	channelID = &cID
}
return s.gatewayWrite(ctx, nil, voiceChannelJoinOp{4, voiceChannelJoinData{&gID, channelID, mute, deaf}})

body, err := s.RequestWithBucketID("GET", EndpointChannelWebhooks(channelID), nil, EndpointChannelWebhooks(channelID), options...)
if err != nil {
	return
}

err = unmarshal(body, &st)

return

s.wsLifecycle.Lock()
s.Lock()

s.DataReady = false

if s.listening != nil {
	close(s.listening)
	s.listening = nil
}
conn := s.wsConn
s.wsConn = nil
voices := make([]*VoiceConnection, 0, len(s.VoiceConnections))
for _, voice := range s.VoiceConnections {
	voices = append(voices, voice)
}
s.Unlock()
for _, voice := range voices {
	voice.engine.stop(ErrVoiceClosed)
}
var err error
if conn != nil {
	// Bound both gate acquisition and the close frame. A stuck writer is
	// interrupted by Close even if it used a background context.
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	err = s.gatewayWriteFrame(ctx, conn, websocket.CloseMessage, websocket.FormatCloseMessage(closeCode, ""), nil)
	cancel()
	closeErr := conn.Close()
	if err == nil {
		err = closeErr
	}
}
s.wsLifecycle.Unlock()
s.handleEvent(disconnectEventType, &Disconnect{})
return err

